type WuKongserverCSharp = {

	-- 创建悟空新容器
	-- @param userId: number 用户ID
	-- @return IUserContainer 返回新创建的悟空容器
	CreateWuKongContainer: (self: IWuKongServer, userId: number) -> IUserContainer,

	-- 设置管理员检查处理器
	-- @param handler: (userId: number) -> boolean 管理员检查处理函数
	SetAdminCheckingHandler: (self: IWuKongServer, handler: (userId: number) -> boolean) -> (),

	-- 序列化悟空容器，得到序列化数据
	-- @param container: IUserContainer 要序列化的容器
	-- @return ContainerStaff 返回序列化后的数据
	SerializeWuKongContainer: (self: IWuKongServer, container: IUserContainer) -> ContainerStaff,

	-- 反序列化悟空容器，提供序列化数据，得到悟空容器
	-- @param userId: number 用户ID
	-- @param staff: ContainerStaff 序列化数据
	-- @return IUserContainer 返回反序列化后的悟空容器
	DeserializeWuKongContainer: (self: IWuKongServer, userId: number, staff: ContainerStaff) -> IUserContainer,

	-- 重置用户容器到指定模板，如果模板名称为空，则使用"正式"
	-- 调用时，用户必须已经登陆且注册到了同步中心
	-- 调用后，会立刻踢出用户，提示其重新登陆
	-- @param userId: number 用户ID
	-- @param templateName: string? 模板名称（可选）
	ResetUserContainer: (self: IWuKongServer, userId: number, templateName: string?) -> (),

	-- 注册悟空容器到同步中心
	-- @param container: IUserContainer 要注册的容器
	-- @return IWuKongRbxFacade 返回注册后的门面实例
	Register: (self: IWuKongServer, container: IUserContainer) -> IWuKongRbxFacade,

	-- 取消注册悟空容器（同步中心）
	-- @param userId: number 用户ID
	UnRegister: (self: IWuKongServer, userId: number) -> (),

	-- 是否注册了悟空容器
	-- @param userId: number 用户ID
	-- @return boolean 返回是否已注册
	IsRegistered: (self: IWuKongServer, userId: number) -> boolean,

	-- 获取所有用户门面
	-- @return {[number]: IWuKongRbxFacade} 返回所有用户门面的字典
	GetAllFacades: (self: IWuKongServer) -> { [number]: IWuKongFacade },

	-- 获取用户门面
	-- @param userId: number 用户ID
	-- @return IWuKongRbxFacade 返回用户门面实例
	GetFacade: (self: IWuKongServer, userId: number) -> IWuKongFacade,

	-- 检查是否存在用户门面
	-- @param userId: number 用户ID
	-- @return boolean 返回是否存在用户门面
	HasFacade: (self: IWuKongServer, userId: number) -> boolean,

	-- 注销
	Dispose: (self: IWuKongClient) -> (),
}

type WuKongServerExtensions = {
	RegisterUser: (self: IWuKongServer, userId: number, userData: any?) -> IWuKongFacade,
	UnregisterUser: (self: IWuKongServer, userId: number) -> {},
}

export type IWuKongServer = WuKongserverCSharp & WuKongServerExtensions
